(function(){
var h=location.hostname;
if(h!=='res.isdc.co.kr'&&h!=='gjcenter.gjcs.or.kr'){
try{
/* 모바일에서 이 오버레이가 실제 화면 크기와 무관하게 조그맣게 보이는 문제 -
   원인은 이 오버레이가 아니라 "띄우려는 그 페이지"에 <meta viewport>가 없는
   경우, 모바일 브라우저가 기본 가상 뷰포트(980px)로 전체 페이지를 렌더링한
   뒤 화면 폭에 맞춰 통째로 축소해버리기 때문(우리 오버레이도 그 축소된
   레이아웃 안에 끼여서 같이 작아짐). 페이지에 뷰포트 태그를 강제로 넣어서
   바로잡는다 - 버튼을 누르면 바로 다른 사이트로 이동하는 임시 화면이라,
   원래 페이지 레이아웃에 영향을 줘도 문제되지 않는다. */
try{
var vp=document.querySelector('meta[name="viewport"]');
if(!vp){vp=document.createElement('meta');vp.setAttribute('name','viewport');document.head.appendChild(vp);}
vp.setAttribute('content','width=device-width, initial-scale=1');
}catch(e){}
var ov=document.createElement('div');
ov.style.cssText='position:fixed;inset:0;z-index:2147483647;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;font-family:-apple-system,sans-serif;';
ov.innerHTML='<div style="background:#fff;color:#111;padding:36px 28px;border-radius:14px;width:min(92vw,380px);box-sizing:border-box;text-align:center;box-shadow:0 10px 40px rgba(0,0,0,0.3);"><div style="font-weight:700;font-size:22px;margin-bottom:24px;">🎾 테니스 예약 바로가기</div><div style="display:flex;flex-direction:column;gap:14px;"><button id="__tnm_go_gj" style="padding:18px 20px;border:none;border-radius:10px;background:#2563eb;color:#fff;font-size:19px;font-weight:600;cursor:pointer;">양벌돔으로 이동</button><button id="__tnm_go_sn" style="padding:18px 20px;border:none;border-radius:10px;background:#1a1a1a;color:#fff;font-size:19px;font-weight:600;cursor:pointer;">성남으로 이동</button><button id="__tnm_cancel" style="padding:12px 20px;border:none;background:transparent;color:#999;font-size:16px;cursor:pointer;">닫기</button></div></div>';
document.body.appendChild(ov);
ov.querySelector('#__tnm_go_gj').onclick=function(){location.href='https://gjcenter.gjcs.or.kr/fmcs/1';};
ov.querySelector('#__tnm_go_sn').onclick=function(){location.href='https://res.isdc.co.kr/index.do';};
ov.querySelector('#__tnm_cancel').onclick=function(){try{ov.remove();}catch(e){}};
}catch(e){alert('바로가기 메뉴 표시 실패: '+e.message);}
return;
}
/* 이전 버전은 여기서 로그인 상태를 추측해 강제로 이동시켰으나, 각 대시보드가 자체 로그인 확인을 하므로 제거함. */
var __gjInitialIslogin=null;
if(h==='gjcenter.gjcs.or.kr'){try{__gjInitialIslogin=(typeof ISLOGIN!=='undefined')?Boolean(ISLOGIN):null;}catch(e){__gjInitialIslogin=null;}}
var b64=(h==='res.isdc.co.kr')?'':'';
;;function decodeUtf8B64(b){var bin=atob(b),pct='';for(var i=0;i<bin.length;i++){var c=bin.charCodeAt(i);pct+='%'+(c<16?'0':'')+c.toString(16);}return decodeURIComponent(pct);}
function __tnmApplyGjHint(str){
if(h!=='gjcenter.gjcs.or.kr'){return str;}
return str.replace('"__GJCS_ISLOGIN_PLACEHOLDER__"',JSON.stringify(__gjInitialIslogin));
}
var __isMobile=(function(){try{var ua=navigator.userAgent||'';if(/iPhone|iPad|iPod|Android/i.test(ua))return true;if(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)return true;}catch(e){}return false;})();
if(__isMobile){
/* 예전엔 document.title에 "테니스"가 있으면(이미 대시보드가 떠있다고 보고)
   그냥 아무것도 안 하고 끝냈는데, 이 가드 때문에 한 번 망가진 상태(init 실패
   등)로 멈추면 다시 북마크릿을 눌러도 계속 조용히 무시돼서 복구가 안 됐다
   (실측 확인 - 아이폰 사파리가 앱을 꺼도 탭 메모리를 살려서 복원하는 경우
   이 증상이 재현됨). 매번 새로 그리는 비용은 거의 없으니, 이 가드 자체를
   없애고 항상 다시 렌더링한다 - 그래야 북마크릿 재실행이 항상 진짜 복구
   수단이 된다. */
var mhtml;
try{mhtml=__tnmApplyGjHint(decodeUtf8B64(b64));}catch(e){alert('디코딩 실패: '+e.message);return;}
try{setTimeout(function(){try{document.open();document.write(mhtml);document.close();try{window.scrollTo(0,0);}catch(e2){}}catch(e3){alert('렌더링 실패: '+e3.message);}},30);}catch(e){alert('렌더링 실패: '+e.message);}
return;
}
var w=null;
try{w=window.__TNM_WIN;}catch(e){}
try{window.__TNM_WIN=null;}catch(e){}
if(!w||w.closed){
try{
var sw=(screen&&screen.availWidth)?screen.availWidth:1280;
var sh=(screen&&screen.availHeight)?screen.availHeight:900;
var ww=Math.min(1860,sw);
var wh=sh-30;
if(wh<700)wh=sh;
w=window.open('','tennis_dashboard','width='+ww+',height='+wh+',left=0,top=0,resizable=yes,scrollbars=yes');
}catch(e){alert('팝업 열기 실패: '+e.message);return;}
}
if(!w){alert('팝업이 차단됐습니다. 팝업 허용 후 다시 시도해주세요.');return;}
try{w.focus();}catch(e){}
/* 모바일 쪽과 같은 이유로 "이미 떠있으면 건너뛰기" 가드를 없앴다 - 한 번
   망가진 채로 멈추면 다시 눌러도 복구가 안 되는 문제가 있었다. 매번 새로
   그리는 비용은 적으니, 항상 다시 렌더링해서 재실행이 진짜 복구 수단이
   되게 한다. */
var html;
try{html=__tnmApplyGjHint(decodeUtf8B64(b64));}catch(e){alert('디코딩 실패: '+e.message);return;}
try{w.document.open();w.document.write(html);w.document.close();}catch(e){try{w.document.body.innerHTML='<div style="padding:40px;color:#e85a5a;font-family:monospace;background:#0f1a14;">렌더링 실패: '+e.message+'</div>';}catch(e2){alert('렌더링 실패: '+e.message);}}
setTimeout(function(){try{if(w&&!w.closed&&w.document&&(!w.document.title||w.document.title.indexOf('테니스')===-1)){var bodyText=(w.document.body&&w.document.body.innerText)||'';var diag='title="'+w.document.title+'", URL='+w.location.href+', bodyLen='+bodyText.length+', readyState='+w.document.readyState;alert('대시보드 로드 실패 진단:\n'+diag+'\n\n이 메시지를 Claude에게 공유해주세요.');}}catch(e){alert('대시보드 로드 실패 (cross-origin): '+e.message);}},1500);
})();
